// Read-only helpers over the snapshot generated by the Python processor (processor/generate_snapshot.py).
import snapshot from "./snapshot.json";

export { snapshot };

const cb77 = () => snapshot.files.DEMO_CB77;

/** Output Value for the first emitted record whose source value matches. */
export function outputFor(sourceValue) {
  const rec = cb77().records.find((r) => r.source.value === sourceValue && r.output);
  return rec ? JSON.parse(rec.output).Value : undefined;
}

export const asJson = (v) => JSON.stringify(v);

export function issueOfType(type) {
  return cb77().issues.find((i) => i.type === type);
}

/** A small slice of the report grid: first `rows` rows of one column. */
export function gridSample(col = "0010", rows = 4) {
  return Object.entries(snapshot.report_grid)
    .filter(([, cols]) => col in cols)
    .slice(0, rows)
    .map(([row, cols]) => ({ row, value: cols[col] }));
}

/** Plain three-field records, as in the approved page copy (report_code is a labelled extra in the data files). */
const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;

/** One-line summary of the representative demo run, built entirely from the processor's run statistics. */
export function runSummary() {
  const { summary: s, groups } = cb77();
  const groupIds = Object.keys(groups);
  const groupPart = groupIds.length
    ? `${plural(groupIds.length, "rijnr group")} (${groupIds.map((id) => `rijnr ${id}: ${groups[id].length}`).join(" \u00b7 ")})`
    : null;
  return [
    `Demo run ${s.formulier_id}`,
    `${s.records_read} records read`,
    `${s.records_emitted} written`,
    plural(s.duplicates, "duplicate"),
    `${s.hierarchy_misses} mapping ${s.hierarchy_misses === 1 ? "miss" : "misses"}`,
    groupPart,
  ]
    .filter(Boolean)
    .join(" \u00b7 ");
}

export function jsonlSample(count = 3) {
  return cb77()
    .output.slice(0, count)
    .map((line) => {
      const { report_code, ...plain } = JSON.parse(line);
      return JSON.stringify(plain);
    });
}
